-- Structured legal pages: an intro paragraph, then "## " sections. Lines "Label : value" render as tables.

INSERT INTO settings (skey, lang, value) VALUES
('legal_updated', '', '2026-10-11'),

('legal_notice', 'fr', 'Conformément aux articles 6-III et 19 de la loi n° 2004-575 du 21 juin 2004 pour la confiance dans l’économie numérique (LCEN), vous trouverez ci-dessous les informations relatives à l’éditeur et à l’hébergeur du site, ainsi que ses conditions d’utilisation.\n\n## Éditeur du site\n\nDénomination : Heaven of Web\nForme juridique : [à compléter]\nSiège social : [à compléter], Angers, France\nSIRET : [à compléter]\nN° TVA intracommunautaire : [à compléter]\nE-mail : [contact@heavenofweb.fr](mailto:contact@heavenofweb.fr)\nTéléphone : [à compléter]\nDirecteur de la publication : [à compléter]\n\n## Hébergement\n\nHébergeur : Hostinger International Ltd.\nAdresse : 61 Lordou Vironos Street, 6023 Larnaca, Chypre\nSite web : [www.hostinger.fr](https://www.hostinger.fr)\n\n## Propriété intellectuelle\n\nL’ensemble des éléments de ce site (textes, logo, graphismes, photographies, mise en page) est la propriété exclusive de Heaven of Web ou de ses clients, qui en ont autorisé la présentation, et est protégé par le Code de la propriété intellectuelle. Toute reproduction, représentation ou adaptation, totale ou partielle, sans autorisation écrite préalable est interdite.\n\nLes marques et logos des clients présentés dans les réalisations appartiennent à leurs titulaires respectifs.\n\n## Responsabilité\n\nHeaven of Web s’efforce de fournir des informations exactes et à jour, sans pouvoir garantir l’absence d’erreur ou d’omission. Les tarifs et délais indiqués lors des échanges ne valent qu’après devis signé.\n\nHeaven of Web ne saurait être tenue responsable du contenu des sites tiers vers lesquels pointent des liens.\n\n## Données personnelles\n\nLe traitement des données transmises via le formulaire de contact est décrit dans notre [politique de confidentialité](/fr/confidentialite).\n\n## Droit applicable\n\nLes présentes mentions légales sont régies par le droit français. En cas de litige, et à défaut de résolution amiable, les tribunaux français seront seuls compétents.'),

('privacy', 'fr', 'Cette politique explique quelles données nous recueillons sur ce site, pourquoi, combien de temps nous les gardons et comment exercer vos droits, conformément au Règlement général sur la protection des données (RGPD) et à la loi Informatique et Libertés.\n\n## Responsable du traitement\n\nResponsable : Heaven of Web\nAdresse : [à compléter], Angers, France\nE-mail : [contact@heavenofweb.fr](mailto:contact@heavenofweb.fr)\n\n## Données collectées\n\nLorsque vous utilisez le formulaire de contact, nous recevons :\n\n- votre nom et votre adresse e-mail ;\n- si vous les indiquez : votre téléphone et le service qui vous intéresse ;\n- votre message.\n\nNous ne collectons aucune donnée sensible et ne vous demandons jamais de créer un compte.\n\n## Finalités et base légale\n\n- Répondre à votre demande et établir un devis : mesures précontractuelles prises à votre demande (article 6.1.b du RGPD).\n- Mesurer la fréquentation du site de façon anonyme : intérêt légitime à améliorer le site (article 6.1.f du RGPD).\n\n## Durée de conservation\n\nMessages du formulaire : 3 ans après notre dernier échange\nStatistiques de visite anonymes : 13 mois\nCookie de session : jusqu’à la fermeture du navigateur\n\n## Destinataires\n\nVos données sont destinées uniquement à Heaven of Web. Elles sont hébergées par Hostinger International Ltd. dans l’Union européenne. Elles ne sont ni vendues, ni louées, ni transmises à des fins publicitaires.\n\n## Cookies et stockage local\n\nCe site n’utilise aucun cookie publicitaire ni traceur tiers, et ses polices sont hébergées localement (aucune requête vers Google).\n\n- Cookie de session « how_sid » : nécessaire à la sécurité du formulaire de contact (protection contre les envois frauduleux). Il est supprimé à la fermeture du navigateur.\n- Stockage local du navigateur : mémorise votre choix concernant les statistiques et l’affichage de l’écran de chargement. Ces informations restent sur votre appareil.\n\nVous pouvez modifier votre choix à tout moment via le lien « Gestion des cookies » en bas de page.\n\n## Mesure d’audience\n\nNous comptons les visites avec un outil interne qui ne dépose aucun cookie et ne conserve pas votre adresse IP : un identifiant anonyme, renouvelé chaque jour, sert uniquement à compter les visiteurs. Si vous refusez les statistiques, aucune visite n’est enregistrée pour vous.\n\n## Vos droits\n\nVous disposez d’un droit d’accès, de rectification, d’effacement, de limitation, d’opposition et de portabilité de vos données. Pour les exercer, écrivez à [contact@heavenofweb.fr](mailto:contact@heavenofweb.fr). Nous répondons dans un délai d’un mois.\n\n## Réclamation\n\nSi vous estimez que vos droits ne sont pas respectés, vous pouvez adresser une réclamation à la CNIL : [www.cnil.fr](https://www.cnil.fr).'),

('legal_notice', 'en', 'In accordance with articles 6-III and 19 of French law no. 2004-575 of 21 June 2004 on confidence in the digital economy (LCEN), you will find below information about the publisher and host of this website and its terms of use.\n\n## Publisher\n\nCompany name : Heaven of Web\nLegal form : [to be completed]\nRegistered office : [to be completed], Angers, France\nCompany number (SIRET) : [to be completed]\nEU VAT number : [to be completed]\nEmail : [contact@heavenofweb.fr](mailto:contact@heavenofweb.fr)\nPhone : [to be completed]\nPublication director : [to be completed]\n\n## Hosting\n\nHost : Hostinger International Ltd.\nAddress : 61 Lordou Vironos Street, 6023 Larnaca, Cyprus\nWebsite : [www.hostinger.com](https://www.hostinger.com)\n\n## Intellectual property\n\nAll content on this website (text, logo, graphics, photographs, layout) belongs to Heaven of Web or to its clients, who have authorised its display, and is protected by intellectual property law. Any reproduction or adaptation without prior written permission is prohibited.\n\nClient brands and logos shown in our projects belong to their respective owners.\n\n## Liability\n\nHeaven of Web strives to provide accurate, up-to-date information but cannot guarantee it is free of errors or omissions. Prices and timelines only apply once a quote has been signed. Heaven of Web is not responsible for the content of third-party websites linked from this site.\n\n## Personal data\n\nHow we handle the data sent through the contact form is described in our [privacy policy](/en/confidentialite).\n\n## Governing law\n\nThis legal notice is governed by French law. In the event of a dispute that cannot be settled amicably, the French courts have sole jurisdiction.'),

('privacy', 'en', 'This policy explains what data we collect on this website, why, how long we keep it and how to exercise your rights, in accordance with the General Data Protection Regulation (GDPR).\n\n## Data controller\n\nController : Heaven of Web\nAddress : [to be completed], Angers, France\nEmail : [contact@heavenofweb.fr](mailto:contact@heavenofweb.fr)\n\n## Data we collect\n\nWhen you use the contact form we receive:\n\n- your name and email address;\n- if you provide them: your phone number and the service you are interested in;\n- your message.\n\nWe never collect sensitive data and never ask you to create an account.\n\n## Purposes and legal basis\n\n- Answering your request and preparing a quote: pre-contractual steps taken at your request (GDPR article 6.1.b).\n- Measuring traffic anonymously: legitimate interest in improving the website (GDPR article 6.1.f).\n\n## Retention\n\nContact form messages : 3 years after our last exchange\nAnonymous visit statistics : 13 months\nSession cookie : until you close your browser\n\n## Recipients\n\nYour data is only used by Heaven of Web and hosted by Hostinger International Ltd. in the European Union. It is never sold, rented or shared for advertising.\n\n## Cookies and local storage\n\nThis website uses no advertising cookies or third-party trackers, and its fonts are self-hosted.\n\n- Session cookie “how_sid”: required to secure the contact form against fraudulent submissions. It is deleted when you close your browser.\n- Browser local storage: remembers your statistics choice and whether the loading screen was shown. This stays on your device.\n\nYou can change your choice at any time with the “Cookie settings” link at the bottom of each page.\n\n## Analytics\n\nWe count visits with an in-house tool that sets no cookies and does not store your IP address: an anonymous identifier, renewed every day, is only used to count visitors. If you refuse statistics, no visit is recorded for you.\n\n## Your rights\n\nYou have the right to access, correct, erase, restrict, object to and port your data. To exercise these rights, email [contact@heavenofweb.fr](mailto:contact@heavenofweb.fr). We reply within one month.\n\n## Complaints\n\nIf you believe your rights are not respected, you can lodge a complaint with the French data protection authority (CNIL): [www.cnil.fr](https://www.cnil.fr).'),

('legal_notice', 'ar', 'وفقًا للمادتين 6-III و19 من القانون الفرنسي رقم 2004-575 الصادر في 21 يونيو 2004 بشأن الثقة في الاقتصاد الرقمي، تجد أدناه المعلومات المتعلقة بناشر الموقع ومستضيفه وشروط استخدامه.\n\n## ناشر الموقع\n\nالاسم التجاري : Heaven of Web\nالشكل القانوني : [يُستكمل]\nالمقر الرئيسي : [يُستكمل]، أنجيه، فرنسا\nرقم التسجيل (SIRET) : [يُستكمل]\nرقم ضريبة القيمة المضافة : [يُستكمل]\nالبريد الإلكتروني : [contact@heavenofweb.fr](mailto:contact@heavenofweb.fr)\nالهاتف : [يُستكمل]\nمدير النشر : [يُستكمل]\n\n## الاستضافة\n\nالمستضيف : Hostinger International Ltd.\nالعنوان : 61 Lordou Vironos Street, 6023 Larnaca، قبرص\nالموقع : [www.hostinger.com](https://www.hostinger.com)\n\n## الملكية الفكرية\n\nجميع عناصر هذا الموقع (نصوص، شعار، تصاميم، صور) ملك لـ Heaven of Web أو لعملائها الذين أذنوا بعرضها، وهي محمية بقانون الملكية الفكرية. يُمنع أي نسخ أو تعديل دون إذن كتابي مسبق.\n\n## المسؤولية\n\nتسعى Heaven of Web إلى تقديم معلومات دقيقة ومحدّثة دون أن تضمن خلوّها من الأخطاء. لا تتحمل Heaven of Web مسؤولية محتوى المواقع الخارجية المرتبطة بهذا الموقع.\n\n## البيانات الشخصية\n\nطريقة معالجة البيانات المرسلة عبر نموذج الاتصال موضّحة في [سياسة الخصوصية](/ar/confidentialite).\n\n## القانون المطبق\n\nيخضع هذا الإشعار القانوني للقانون الفرنسي. وفي حال النزاع وتعذّر الحل الودي، تختص المحاكم الفرنسية وحدها.'),

('privacy', 'ar', 'توضح هذه السياسة البيانات التي نجمعها على هذا الموقع وسبب جمعها ومدة الاحتفاظ بها وكيفية ممارسة حقوقك، وفقًا للائحة العامة لحماية البيانات (RGPD).\n\n## المسؤول عن المعالجة\n\nالمسؤول : Heaven of Web\nالعنوان : [يُستكمل]، أنجيه، فرنسا\nالبريد الإلكتروني : [contact@heavenofweb.fr](mailto:contact@heavenofweb.fr)\n\n## البيانات التي نجمعها\n\nعند استخدام نموذج الاتصال نتلقى:\n\n- اسمك وبريدك الإلكتروني؛\n- إن ذكرتهما: رقم هاتفك والخدمة التي تهمك؛\n- رسالتك.\n\n## الأغراض والأساس القانوني\n\n- الرد على طلبك وإعداد عرض السعر: إجراءات سابقة للتعاقد بطلب منك.\n- قياس الزيارات بشكل مجهول: مصلحة مشروعة في تحسين الموقع.\n\n## مدة الحفظ\n\nرسائل نموذج الاتصال : 3 سنوات بعد آخر تواصل\nإحصاءات الزيارات المجهولة : 13 شهرًا\nملف تعريف الجلسة : حتى إغلاق المتصفح\n\n## ملفات تعريف الارتباط والتخزين المحلي\n\nلا يستخدم هذا الموقع أي ملفات تعريف ارتباط إعلانية أو أدوات تتبع خارجية.\n\n- ملف الجلسة «how_sid»: ضروري لحماية نموذج الاتصال، ويُحذف عند إغلاق المتصفح.\n- التخزين المحلي للمتصفح: يحفظ اختيارك بشأن الإحصاءات، ويبقى على جهازك.\n\nيمكنك تغيير اختيارك في أي وقت عبر رابط «إدارة ملفات تعريف الارتباط» أسفل الصفحة.\n\n## قياس الزيارات\n\nنعدّ الزيارات بأداة داخلية لا تستخدم ملفات تعريف الارتباط ولا تحفظ عنوان IP الخاص بك. إذا رفضت الإحصاءات فلن تُسجَّل أي زيارة لك.\n\n## حقوقك\n\nلك الحق في الاطلاع على بياناتك وتصحيحها وحذفها وتقييد معالجتها والاعتراض عليها ونقلها، بالكتابة إلى [contact@heavenofweb.fr](mailto:contact@heavenofweb.fr). نرد خلال شهر واحد.\n\n## الشكوى\n\nيمكنك تقديم شكوى إلى الهيئة الفرنسية لحماية البيانات (CNIL): [www.cnil.fr](https://www.cnil.fr).')
ON DUPLICATE KEY UPDATE value = VALUES(value);

